 24	const entireCommandMarker = "entire hooks " + AgentName
 25	
 26	// kindGroup / kindHooks are headerEvent's block kinds: a matcher-group
 27	// header ([[hooks.<Event>]]) versus a hook-entry block
 28	// ([[hooks.<Event>.hooks]]).
 29	const (
 30		kindGroup = "group"
 31		kindHooks = "hooks"
 32	)
 33	
 34	// configHookEntry is one hook handler we manage in the project config.
 35	type configHookEntry struct {
 36		Event   string // PascalCase sarvam event key
 37		Name    string // stable logical name (used only for matching our entries)
 38		Command string // exact command string
 39	}
 40	
 41	type tomlBlock struct {
 42		header string   // raw header line, "" for the preamble block
 43		body   []string // lines after the header until the next header
 44	}
 45	
 46	// headerLinePattern matches a TOML table or array-of-tables header: opening
 47	// brackets, a key without ] characters, matching closing brackets, and an
 48	// optional trailing comment. Continuation lines of multi-line arrays or
 49	// strings ("[\"a\", \"b\"],") do not match, so they stay in the body of the
 50	// block that opened them instead of becoming phantom headers.
 51	var headerLinePattern = regexp.MustCompile(`^\[+[^\]]*\]+\s*(?:#.*)?$`)
 52	
 53	func isHeaderLine(line string) bool {
 54		return headerLinePattern.MatchString(line)
 55	}
 56	
 57	func headerEvent(header string) (event string, kind string) {
 58		trimmed := strings.TrimSpace(header)
 59		// A trailing comment is not part of the key: [[hooks.Stop]] # nightly.
 60		// Quoted keys containing '#' are unaffected in practice because the
 61		// events we manage are bare, unquoted names.
 62		if i := strings.Index(trimmed, "#"); i >= 0 {
 63			trimmed = strings.TrimSpace(trimmed[:i])
 64		}
 65		for _, prefix := range []string{"[[hooks.", "[hooks."} {
 66			if strings.HasPrefix(trimmed, prefix) {
 67				rest := strings.TrimSuffix(strings.TrimPrefix(trimmed, prefix), "]")
 68				rest = strings.TrimSuffix(rest, "]")
 69				switch {
 70				case strings.HasSuffix(rest, ".hooks"):
 71					return strings.TrimSuffix(rest, ".hooks"), kindHooks
 72				default:
 73					return rest, kindGroup
 74				}
 75			}
 76		}
 77		return "", ""
 78	}
 79	
 80	// netBracketsOutsideQuotes counts '[' minus ']' outside quoted strings and
 81	// comments on a single line — enough to know whether the line leaves a
 82	// multi-line array still open.
 83	func netBracketsOutsideQuotes(line string) int {
 84		depth := 0
 85		var quote byte
 86		for i := 0; i < len(line); i++ {
 87			ch := line[i]
 88			switch {
 89			case quote != 0:
 90				if ch == '\\' && quote == '"' && i+1 < len(line) {
 91					i++ // skip the escaped character
 92					continue
 93				}
 94				if ch == quote {
 95					quote = 0
 96				}
 97			case ch == '"' || ch == '\'':
 98				quote = ch
 99			case ch == '#':
100				return depth // comment runs to end of line
101			case ch == '[':
102				depth++
103			case ch == ']':
104				depth--
105			}
106		}
107		return depth
108	}
109	
110	// parseConfigBlocks splits the file into header-anchored blocks. The first
111	// block (preamble) has an empty header and holds everything before the first
112	// table header. Lines inside an open multi-line string (""" or ”') or an
113	// open multi-line array are always body lines — a line that merely looks
114	// like a header inside such a value must not split the block. Header lines
115	// are stored verbatim — indentation and line endings are the author's —
116	// and the returned flag records whether the file ended with a newline, so
117	// serialization round-trips byte-for-byte.
118	func parseConfigBlocks(content string) ([]tomlBlock, bool) {
119		lines := strings.Split(content, "\n")
120		// A trailing newline produces one empty final element; remember it so
121		// serialization round-trips.
122		trailingNewline := len(lines) > 0 && lines[len(lines)-1] == ""
123		if trailingNewline {
124			lines = lines[:len(lines)-1]
125		}
126		blocks := []tomlBlock{{}}
127		multiLineString := "" // "" outside, otherwise the open delimiter
128		arrayDepth := 0       // open multi-line arrays: body lines until closed
129		for _, line := range lines {
130			if multiLineString != "" {
131				if strings.Count(line, multiLineString)%2 == 1 {
132					multiLineString = ""
133				}
134				blocks[len(blocks)-1].body = append(blocks[len(blocks)-1].body, line)
135				continue
136			}
137			if arrayDepth > 0 {
138				blocks[len(blocks)-1].body = append(blocks[len(blocks)-1].body, line)
139				arrayDepth += netBracketsOutsideQuotes(line)
140				if arrayDepth < 0 {
141					arrayDepth = 0
142				}
143				continue
144			}
145			if isHeaderLine(strings.TrimSpace(line)) {
146				blocks = append(blocks, tomlBlock{header: line})
147				continue
148			}
149			blocks[len(blocks)-1].body = append(blocks[len(blocks)-1].body, line)
150			if depth := netBracketsOutsideQuotes(line); depth > 0 {
151				arrayDepth = depth
152				continue
153			}
154			for _, delimiter := range []string{`"""`, `'''`} {
155				if strings.Count(line, delimiter)%2 == 1 {
156					multiLineString = delimiter
157					break
158				}
159			}
160		}
161		return blocks, trailingNewline
162	}
163	
164	// serializeConfigBlocks is the inverse of parseConfigBlocks; when the file
165	// had no trailing newline, the last line keeps its missing newline.
166	func serializeConfigBlocks(blocks []tomlBlock, trailingNewline bool) string {
167		var b strings.Builder
168		for _, block := range blocks {
169			if block.header != "" {
170				b.WriteString(block.header)
171				b.WriteByte('\n')
172			}
173			for _, line := range block.body {
174				b.WriteString(line)
175				b.WriteByte('\n')
176			}
177		}
178		out := b.String()
179		if !trailingNewline && strings.HasSuffix(out, "\n") {
180			out = out[:len(out)-1]
181		}
182		return out
183	}
184	
185	// entryCommand returns the command value of a hook-entry block, or "".
186	func entryCommand(block tomlBlock) string {
187		for _, line := range block.body {
188			key, value, ok := parseKeyValue(line)
189			if ok && key == "command" {
190				return value
191			}
192		}
193		return ""
194	}
195	
196	func entryIsCommandType(block tomlBlock) bool {
197		for _, line := range block.body {
198			key, value, ok := parseKeyValue(line)
199			if ok && key == "type" && value == "command" {
200				return true
201			}
202		}
203		return false
204	}
205	
206	// isEntireEntry reports whether a hook-entry block belongs to this adapter.
207	func isEntireEntry(block tomlBlock) bool {
208		if !entryIsCommandType(block) {
209			return false
210		}
211		command := entryCommand(block)
212		return command != "" && strings.Contains(command, entireCommandMarker)
213	}
214	
215	// parseKeyValue parses a single `key = value` TOML line, decoding basic and
216	// literal strings. Booleans and numbers come back raw. An unquoted trailing
217	// comment is stripped first: an entry line like `type = "command" # entire`
218	// must still be recognized as ours (otherwise the next install duplicates
219	// it), and a commented command line must decode to the exact command so a
220	// repeat install leaves the line — comment included — untouched.
221	func parseKeyValue(line string) (key string, value string, ok bool) {
222		trimmed := strings.TrimSpace(line)
223		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
224			return "", "", false
225		}
226		eq := strings.Index(trimmed, "=")
227		if eq < 0 {
228			return "", "", false
229		}
230		key = strings.TrimSpace(trimmed[:eq])
231		value = strings.TrimSpace(stripTrailingComment(strings.TrimSpace(trimmed[eq+1:])))
232		if len(value) >= 2 {
233			if value[0] == '"' && value[len(value)-1] == '"' {
234				return key, unescapeBasicString(value[1 : len(value)-1]), true
235			}
236			if value[0] == '\'' && value[len(value)-1] == '\'' {
237				return key, value[1 : len(value)-1], true
238			}
239		}
240		return key, value, true
241	}
242	
243	// stripTrailingComment removes an unquoted TOML comment from a value: the
244	// first '#' outside any quoted string ends the value. Quoted '#' characters
245	// survive. A value that never closes its quote keeps the '#' — malformed
246	// input is left as-is rather than guessed at.
247	func stripTrailingComment(value string) string {
248		var quote byte
249		for i := 0; i < len(value); i++ {
250			ch := value[i]
251			switch {
252			case quote != 0:
253				if ch == '\\' && quote == '"' && i+1 < len(value) {
254					i++ // skip the escaped character
255					continue
256				}
257				if ch == quote {
258					quote = 0
259				}
260			case ch == '"' || ch == '\'':
261				quote = ch
262			case ch == '#':
263				return strings.TrimRight(value[:i], " \t")
264			}
265		}
266		return value
267	}
268	
269	func unescapeBasicString(s string) string {
270		var b strings.Builder
271		for i := 0; i < len(s); i++ {
272			if s[i] == '\\' && i+1 < len(s) {
273				i++
274				switch s[i] {
275				case 'n':
276					b.WriteByte('\n')
277				case 't':
278					b.WriteByte('\t')
279				case 'r':
280					b.WriteByte('\r')
281				default:
282					b.WriteByte(s[i])
283				}
284				continue
285			}
286			b.WriteByte(s[i])
287		}
288		return b.String()
289	}
290	
291	// encodeTOMLString renders s as a TOML basic string.
292	func encodeTOMLString(s string) string {
293		var b strings.Builder
294		b.WriteByte('"')
295		for _, r := range s {
296			switch r {
297			case '"':
298				b.WriteString("\\\"")
299			case '\\':
300				b.WriteString("\\\\")
301			case '\n':
302				b.WriteString("\\n")
303			case '\t':
304				b.WriteString("\\t")
305			case '\r':
306				b.WriteString("\\r")
307			default:
308				b.WriteRune(r)
309			}
310		}
311		b.WriteByte('"')
312		return b.String()
313	}
314	
315	func newEntryBlocks(event, command string) []tomlBlock {
316		return []tomlBlock{
317			{header: fmt.Sprintf("[[hooks.%s]]", event)},
318			{header: fmt.Sprintf("[[hooks.%s.hooks]]", event), body: []string{
319				"type = \"command\"",
320				"command = " + encodeTOMLString(command),
321			}},
322		}
323	}
324	
325	// repairParentlessHooks inserts the missing [[hooks.<Event>]] group headers
326	// the sarvam docs' example leads users to omit: without them the whole hooks
327	// table fails to parse ("invalid type: map, expected a sequence") and the CLI
328	// silently drops every hook. Inserting the header turns the map into the
329	// array of one matcher group, keeping the author's entries.
330	func repairParentlessHooks(blocks []tomlBlock) []tomlBlock {
331		out := make([]tomlBlock, 0, len(blocks)+len(hookSpecs))
332		seenGroup := map[string]bool{}
333		for _, block := range blocks {
334			event, kind := headerEvent(block.header)
335			if event != "" && kind == kindHooks && !seenGroup[event] {
336				if isManagedEvent(event) {
337					out = append(out, tomlBlock{header: fmt.Sprintf("[[hooks.%s]]", event)})
338					// One synthetic group header is the repair: every
339					// parentless entry of the event joins it. Without this
340					// mark, a second parentless entry would get its own
341					// header and silently split the user's entries into
342					// separate matcher groups.
343					seenGroup[event] = true
344				}
345			}
346			if event != "" && kind == kindGroup {
347				seenGroup[event] = true
348			}
349			out = append(out, block)
350		}
351		return out
352	}
353	
354	func isManagedEvent(event string) bool {
355		for _, spec := range hookSpecs {
356			if spec.SarvamEvent == event {
357				return true
358			}
359		}
360		return false
361	}
362	
363	// checkNoMapFormEvents rejects the single-bracket table form for events we
364	// manage — the matcher-group header [hooks.<Event>] and the entry header
365	// [hooks.<Event>.hooks] alike: appending an array-of-tables next to a table
366	// definition is a TOML type conflict, and the CLI would silently drop every
367	// hook. Failing loudly beats corrupting a config the user must fix by hand
368	// anyway.
369	func checkNoMapFormEvents(blocks []tomlBlock) error {
370		for _, block := range blocks {
371			event, kind := headerEvent(block.header)
372			if event == "" || !isManagedEvent(event) {
373				continue
374			}
375			if kind != kindGroup && kind != kindHooks {
376				continue
377			}
378			if !strings.HasPrefix(strings.TrimSpace(block.header), "[[") {
379				return fmt.Errorf(".sarvam/config.toml defines hooks.%s as a table (%s); the sarvam CLI requires arrays — replace the header with the [[...]] form and rerun", event, strings.TrimSpace(block.header))
380			}
381		}
382		return nil
383	}
384	
385	// upsertHookEntries installs the given entries, returning how many hook
386	// handlers were added or updated. Unrelated config content is untouched.
387	func upsertHookEntries(path string, entries []configHookEntry, force bool) (int, error) {
388		blocks, trailingNewline, err := loadBlocks(path)
389		if err != nil {
390			return 0, err
391		}
392		if err := checkNoMapFormEvents(blocks); err != nil {
393			return 0, err
394		}
395		original := serializeConfigBlocks(blocks, trailingNewline)
396		if force {
397			var removedEvents map[string]bool
398			blocks, removedEvents = dropEntireEntries(blocks)
399			// The dropped entries strand their [[hooks.<Event>]] group headers;
400			// without this clean-up every force install would leave another
401			// empty group behind.
402			blocks = dropEmptyManagedGroups(blocks, removedEvents)
403		}
404		blocks = repairParentlessHooks(blocks)
405	
406		count := 0
407		for _, entry := range entries {
408			if upsertOne(&blocks, entry) {
409				count++
410			}
411		}
412		// Zero entries added or updated can still mean the blocks changed: a
413		// parentless repair must reach the file, or the CLI keeps rejecting the
414		// whole hooks table while install-hooks reports nothing happened. And
415		// with no change at all, the author's bytes stay untouched.
416		if count == 0 && serializeConfigBlocks(blocks, trailingNewline) == original {
417			return 0, nil
418		}
419		if err := saveBlocks(path, blocks, trailingNewline); err != nil {
420			return 0, err
421		}
422		return count, nil
423	}
424	
425	func upsertOne(blocks *[]tomlBlock, entry configHookEntry) bool {
426		// Update in place when an owned entry exists.
427		for i, block := range *blocks {
428			event, kind := headerEvent(block.header)
429			if event != entry.Event || kind != kindHooks {
430				continue
431			}
432			if !isEntireEntry(block) {
433				continue
434			}
435			if entryCommand(block) == entry.Command {
436				return false
437			}
438			for j, line := range block.body {
439				if key, _, ok := parseKeyValue(line); ok && key == "command" {
440					(*blocks)[i].body[j] = "command = " + encodeTOMLString(entry.Command)
441					return true
442				}
443			}
444		}
445	
446		// Insert after the event's last hook entry when one exists; otherwise
447		// open a fresh group at the end of the hooks region (or EOF).
448		insertAt := -1
449		lastHooksRegion := -1
450		for i, block := range *blocks {
451			event, kind := headerEvent(block.header)
452			if event == "" {
453				continue
454			}
455			if kind == kindHooks && event == entry.Event {
456				insertAt = i + 1
457			}
458			if trimmed := strings.TrimSpace(block.header); strings.HasPrefix(trimmed, "[hooks.") || strings.HasPrefix(trimmed, "[[hooks.") {
459				lastHooksRegion = i + 1
460			}
461		}
462		at := len(*blocks)
463		if insertAt >= 0 {
464			at = insertAt
465		} else if lastHooksRegion >= 0 {
466			at = lastHooksRegion
467		}
468		newBlocks := newEntryBlocks(entry.Event, entry.Command)
469		out := make([]tomlBlock, 0, len(*blocks)+len(newBlocks))
470		out = append(out, (*blocks)[:at]...)
471		out = append(out, newBlocks...)
472		out = append(out, (*blocks)[at:]...)
473		*blocks = out
474		return true
475	}
476	
477	// removeHookEntries deletes every entry this adapter owns, plus the empty
478	// matcher-group headers those entries strand behind. A config holding none
479	// of our entries is left byte-for-byte untouched.
480	func removeHookEntries(path string) error {
481		blocks, trailingNewline, err := loadBlocks(path)
482		if err != nil {
483			return err
484		}
485		if len(blocks) == 1 && len(blocks[0].body) == 0 && blocks[0].header == "" {
486			return nil // no config at all
487		}
488		kept, removedEvents := dropEntireEntries(blocks)
489		kept = dropEmptyManagedGroups(kept, removedEvents)
490		if serializeConfigBlocks(kept, trailingNewline) == serializeConfigBlocks(blocks, trailingNewline) {
491			// Nothing we own to remove: leave the author's bytes alone.
492			return nil
493		}
494		return saveBlocks(path, kept, trailingNewline)
495	}
496	
497	// dropEntireEntries deletes every entry this adapter owns and reports which
498	// events lost one, so the group cleanup that follows only removes headers
499	// our own entries stranded.
500	func dropEntireEntries(blocks []tomlBlock) ([]tomlBlock, map[string]bool) {
501		removedEvents := map[string]bool{}
502		out := make([]tomlBlock, 0, len(blocks))
503		for _, block := range blocks {
504			event, kind := headerEvent(block.header)
505			if event != "" && kind == kindHooks && isEntireEntry(block) {
506				removedEvents[event] = true
507				continue
508			}
509			out = append(out, block)
510		}
511		return out, removedEvents
512	}
513	
514	// dropEmptyManagedGroups removes [[hooks.<Event>]] group headers that our
515	// removed entries leave stranded: an empty group goes only when the event
516	// lost one of our owned entries in this pass and no same-event
517	// [[hooks.<Event>.hooks]] entry immediately follows it — the parent
518	// relationship TOML array-of-tables gives an entry. A group that still
519	// carries content (a matcher) always stays, and a group the user authored
520	// alone — including for legacy events an older release installed — is
521	// theirs, never ours to clean.
522	func dropEmptyManagedGroups(blocks []tomlBlock, removedEvents map[string]bool) []tomlBlock {
523		out := make([]tomlBlock, 0, len(blocks))
524		for i, block := range blocks {
525			event, kind := headerEvent(block.header)
526			if event != "" && kind == kindGroup && removedEvents[event] &&
527				len(block.body) == 0 && !followedBySameEventEntry(blocks, i) {
528				continue
529			}
530			out = append(out, block)
531		}
532		return out
533	}
534	
535	// followedBySameEventEntry reports whether the block after blocks[i] is a
536	// hook entry of the same event. parseConfigBlocks opens every header its own
537	// block, so the next block is exactly where an entry's parent group ends.
538	func followedBySameEventEntry(blocks []tomlBlock, groupIndex int) bool {
539		if groupIndex+1 >= len(blocks) {
540			return false
541		}
542		groupEvent, _ := headerEvent(blocks[groupIndex].header)
543		event, kind := headerEvent(blocks[groupIndex+1].header)
544		return event == groupEvent && kind == kindHooks
545	}
546	
547	func hookEntryInstalled(path, event, command string) bool {
548		blocks, _, err := loadBlocks(path)
549		if err != nil {
550			return false
551		}
552		// An entry without its [[hooks.<Event>]] matcher-group header is not
553		// installed in any way the CLI can parse — the whole hooks table fails
554		// with "invalid type: map, expected a sequence" — so the group header
555		// must precede the entry for it to count. A single-bracket group is a
556		// table form the CLI rejects equally, so it does not count either.
557		seenGroup := false
558		for _, block := range blocks {
559			e, kind := headerEvent(block.header)
560			if e == "" {
561				continue
562			}
563			if kind == kindGroup && e == event {
564				seenGroup = strings.HasPrefix(strings.TrimSpace(block.header), "[[")
565				continue
566			}
567			if kind == kindHooks && e == event && seenGroup &&
568				isEntireEntry(block) && entryCommand(block) == command {
569				return true
570			}
571		}
572		return false
573	}
574	
575	func loadBlocks(path string) ([]tomlBlock, bool, error) {
576		data, err := os.ReadFile(path)
577		if os.IsNotExist(err) {
578			return []tomlBlock{{}}, true, nil
579		}
580		if err != nil {
581			return nil, true, err
582		}
583		if len(strings.TrimSpace(string(data))) == 0 {
584			return []tomlBlock{{}}, true, nil
585		}
586		blocks, trailingNewline := parseConfigBlocks(string(data))
587		return blocks, trailingNewline, nil
588	}
589	
590	func saveBlocks(path string, blocks []tomlBlock, trailingNewline bool) error {
591		content := serializeConfigBlocks(blocks, trailingNewline)
592		// filepath.Dir is separator-aware: on Windows the config path carries
593		// backslashes, where a hand-rolled "/" split would return "." and leave
594		// the .sarvam directory uncreated.
595		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
596			return err
597		}
598		mode := os.FileMode(0o600)
599		if existing, err := os.Stat(path); err == nil {
600			mode = existing.Mode().Perm()
601		}
602		return os.WriteFile(path, []byte(content), mode)
603	}

