379	// isNativeRolloutPath reports whether the path names one of sarvam's own
380	// rollout transcripts (rollout-<timestamp>-<thread>.jsonl), which write
381	// targets must never touch.
382	func isNativeRolloutPath(path string) bool {
383		base := filepath.Base(path)
384		return strings.HasPrefix(base, "rollout-") && strings.HasSuffix(base, ".jsonl")
385	}
