    14	// CompactTranscript projects the native rollout JSONL into Entire
    15	// Transcript Format: one v:1 unified record per line, the shape the
    16	// server's unified parser admits (isUnifiedTranscript requires a
    17	// top-level content array on the first line) and renders — the same
    18	// envelope qwen's and grok's compactors emit. The earlier projection
    19	// mirrored the wire shapes Entire's in-CLI compactor READS
    20	// ({"type","message":{…}}), which the server rejects: checkpoints stored
    21	// it, but the session page rendered nothing.
    22	//
    23	// Projection:
    24	//
    25	//	response_item message/user      -> user line, content [{"text": …}]
    26	//	  (input_text, minus the injected <environment_context> harness block)
    27	//	response_item message/assistant -> assistant line, content
    28	//	  [{"type":"text","text":…}]
    29	//	function_call                   -> assistant line with a tool_use block;
    30	//	  the matching function_call_output is nested as the block's result,
    31	//	  with a non-zero exec exit code reported as status "error"
    32	//
    33	// Developer messages, reasoning, and the event stream are dropped: none of
    34	// them belong in a checkpoint transcript.
    35	//
    36	// The input is a temp copy of an already-redacted snapshot, so a final line
    37	// without a trailing newline is finished data and is kept when it parses —
    38	// unlike the live-transcript readers, which must never cover a
    39	// half-written record.
    40	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
    41		lines, err := readFinishedRolloutLines(sessionRef)
    42		if err != nil {
    43			if os.IsNotExist(err) {
    44				lines = nil
    45			} else {
    46				return protocol.CompactTranscriptResponse{}, err
    47			}
    48		}
    49	
    50		// First pass: the CLI version from session_meta and each call's output,
    51		// so a tool_use block can nest the result that the rollout records as
    52		// a separate, later line.
    53		cliVersion := "unknown"
    54		toolResults := map[string]compactToolResult{}
    55		for _, line := range lines {
    56			if line.Type == "session_meta" {
    57				var meta struct {
    58					CLIVersion string `json:"cli_version"`
    59				}
    60				if json.Unmarshal(line.Payload, &meta) == nil && strings.TrimSpace(meta.CLIVersion) != "" {
    61					cliVersion = strings.TrimSpace(meta.CLIVersion)
    62				}
    63				continue
    64			}
    65			if line.Type != rolloutLineTypeResponseItem {
    66				continue
    67			}
    68			var probe struct {
    69				Type string `json:"type"`
    70			}
    71			if json.Unmarshal(line.Payload, &probe) != nil || probe.Type != "function_call_output" {
    72				continue
    73			}
    74			var output rolloutFunctionCallOutput
