    56			if line.Type == "session_meta" {
    57				var meta struct {
    58					CLIVersion string `json:"cli_version"`
    59				}
    60				if json.Unmarshal(line.Payload, &meta) == nil && strings.TrimSpace(meta.CLIVersion) != "" {
    61					cliVersion = strings.TrimSpace(meta.CLIVersion)
    62				}
    63				continue
    64			}
    65			if line.Type != rolloutLineTypeResponseItem {
    66				continue
    67			}
    68			var probe struct {
    69				Type string `json:"type"`
    70			}
