 55		// Sarvam Code needs a logged-in CLI with network access, so the suite
 56		// only runs when explicitly requested.
 57		if os.Getenv("E2E_AGENT") != "sarvam" {
 58			return
 59		}
 60		Register(&Sarvam{})
