 67		*TmuxSession
 68	}
 70	func (s *sarvamSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 71		return s.TmuxSession.WaitFor(pattern, time.Duration(float64(timeout)*sarvamTimeoutMultiplier))
 72	}
