 78	func (s *Sarvam) TimeoutMultiplier() float64 { return sarvamTimeoutMultiplier }
 79	func (s *Sarvam) IsExternalAgent() bool      { return true }
 81	// sarvamTransientPhrases are anchored phrases sarvam's TUI actually prints
 82	// when a request fails transiently. The screen capture also contains
 83	// ordinary content — line numbers, ports, the word "timeout" in code or
 84	// command output — so bare numbers or single words would turn real
 85	// failures into retried transients; each phrase carries its surrounding
 86	// words instead.
 87	var sarvamTransientPhrases = []string{
 88		"429 too many requests",
 89		"rate limit",
 90		"overloaded",
 91		"503 service unavailable",
 92		"500 internal server error",
 93		"econnreset",
 94		"etimedout",
 95		"operation timed out",
 96		"deadline exceeded",
 97	}
 99	func (s *Sarvam) IsTransientError(out Output, _ error) bool {
100		combined := strings.ToLower(out.Stdout + out.Stderr)
101		for _, phrase := range sarvamTransientPhrases {
102			if strings.Contains(combined, phrase) {
103				return true
104			}
105		}
106		return false
107	}
109	func (s *Sarvam) Bootstrap() error {
110		bin, err := exec.LookPath(s.Binary())
111		if err != nil {
112			return fmt.Errorf("%s not in PATH: %w", s.Binary(), err)
113		}
114		// The suite trusts repos and seeds [hooks.state] into the CLI's user
115		// config — both write real state — so it must run against a disposable
116		// SARVAM_HOME, never the developer's actual ~/.sarvam.
117		home := os.Getenv("SARVAM_HOME")
118		if home == "" {
119			return errors.New("E2E_AGENT=sarvam requires SARVAM_HOME to point at a disposable home (e.g. $(mktemp -d)): the suite writes directory trust and hook state into the CLI's user config")
120		}
121		userHome, err := os.UserHomeDir()
122		if err != nil {
123			return fmt.Errorf("resolving the user home to locate the sarvam keyring: %w", err)
124		}
125		if filepath.Clean(home) == filepath.Join(userHome, ".sarvam") {
126			return fmt.Errorf("E2E_AGENT=sarvam refuses to run with SARVAM_HOME at the real %s: point it at a disposable home (e.g. $(mktemp -d))", filepath.Join(userHome, ".sarvam"))
127		}
128		// sarvam-code keeps its credentials in $SARVAM_HOME/keyring, so a
129		// disposable home starts unauthenticated and the very first exec run
130		// would fail. Copy the real keyring over, then prove the CLI reports a
131		// signed-in state before any test runs.
132		realKeyring := filepath.Join(userHome, ".sarvam", "keyring")
133		if _, statErr := os.Stat(realKeyring); os.IsNotExist(statErr) {
134			return fmt.Errorf("no sarvam keyring at %s: run sarvam-code login once in the real home so the disposable home can inherit the credentials", realKeyring)
135		}
136		if err := copyTree(realKeyring, filepath.Join(home, "keyring")); err != nil {
137			return fmt.Errorf("copying the sarvam keyring into the disposable SARVAM_HOME %s: %w", home, err)
138		}
139		cmd := exec.Command(bin, "login", "status")
140		cmd.Env = append(os.Environ(), "SARVAM_HOME="+home)
141		out, loginErr := cmd.CombinedOutput()
142		if loginErr != nil || strings.Contains(string(out), "Not logged in") {
143			return fmt.Errorf("sarvam-code is not authenticated in the disposable SARVAM_HOME %s (keyring copied from %s): %s", home, realKeyring, strings.TrimSpace(string(out)))
144		}
145		return nil
146	}
148	// copyTree copies a directory (or a single file) recursively. The keyring
149	// is a handful of small credential files, so plain reads and writes
150	// suffice.
151	func copyTree(src, dst string) error {
152		info, err := os.Stat(src)
153		if err != nil {
154			return err
155		}
156		if !info.IsDir() {
157			return copyTreeFile(src, dst, info.Mode().Perm())
158		}
159		return filepath.WalkDir(src, func(path string, d fs.DirEntry, walkErr error) error {
160			if walkErr != nil {
161				return walkErr
162			}
163			rel, err := filepath.Rel(src, path)
164			if err != nil {
165				return err
166			}
167			target := filepath.Join(dst, rel)
168			if d.IsDir() {
169				return os.MkdirAll(target, 0o700)
170			}
171			entryInfo, err := d.Info()
172			if err != nil {
173				return err
174			}
175			return copyTreeFile(path, target, entryInfo.Mode().Perm())
176		})
177	}
179	func copyTreeFile(src, dst string, mode os.FileMode) error {
180		data, err := os.ReadFile(src)
181		if err != nil {
182			return err
183		}
184		if err := os.MkdirAll(filepath.Dir(dst), 0o700); err != nil {
185			return err
186		}
187		return os.WriteFile(dst, data, mode)
188	}
190	// trustRepo runs a throwaway headless prompt so sarvam records directory
191	// trust in its user config the way first-run acceptance would. Without it the
192	// TUI opens with a trust dialog instead of the composer.
193	func (s *Sarvam) trustRepo(ctx context.Context, dir string) error {
194		bin, err := exec.LookPath(s.Binary())
195		if err != nil {
196			return fmt.Errorf("%s not in PATH: %w", s.Binary(), err)
197		}
198		trustCtx, cancel := context.WithTimeout(ctx, 90*time.Second)
199		defer cancel()
200		cmd := exec.CommandContext(trustCtx, bin, "exec", "--skip-git-repo-check", "-C", dir, "Reply with the single word: ok")
201		cmd.Dir = dir
202		cmd.Env = os.Environ()
203		if out, err := cmd.CombinedOutput(); err != nil {
204			return fmt.Errorf("trust run for %s failed: %w\n%s", dir, err, out)
205		}
206		return nil
207	}
209	func (s *Sarvam) RunPrompt(ctx context.Context, dir string, prompt string, _ ...Option) (Output, error) {
210		session, err := s.StartSession(ctx, dir)
211		if err != nil {
212			return Output{}, err
213		}
214		defer func() { _ = session.Close() }()
216		sess, ok := session.(*sarvamSession)
217		if !ok {
218			return Output{}, fmt.Errorf("unexpected session type %T", session)
219		}
220		display := s.Binary() + " (tmux) " + fmt.Sprintf("%q", prompt)
221		if _, err := sess.SendAndWait(prompt, s.PromptPattern(), 3*time.Minute); err != nil {
222			return Output{Command: display, Stdout: sess.Capture()}, err
223		}
224		return Output{Command: display, Stdout: sess.Capture()}, nil
225	}
227	func (s *Sarvam) StartSession(ctx context.Context, dir string) (Session, error) {
228		if err := s.trustRepo(ctx, dir); err != nil {
229			return nil, err
230		}
231		if err := seedSarvamHookTrust(dir); err != nil {
232			return nil, fmt.Errorf("seed hook trust: %w", err)
233		}
235		name := fmt.Sprintf("sarvam-test-%d", time.Now().UnixNano())
236		sess, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, s.Binary())
237		if err != nil {
238			return nil, err
239		}
240		if err := sess.SetBusyPattern(`\(esc to interrupt\)`); err != nil {
241			_ = sess.Close()
242			return nil, fmt.Errorf("compile sarvam busy pattern: %w", err)
243		}
244		if _, err := sess.WaitFor(s.PromptPattern(), 60*time.Second); err != nil {
245			_ = sess.Close()
246			return nil, fmt.Errorf("waiting for initial prompt: %w", err)
247		}
248		// With trust and hook state pre-seeded, the TUI must come up review-free.
249		// A lingering banner means the trusted_hash constants no longer match
250		// this sarvam-code version's derivation — hooks would silently never
251		// fire, so fail loudly instead of running dead tests.
252		time.Sleep(2 * time.Second)
253		if strings.Contains(sess.Capture(), sarvamReviewBanner) {
254			_ = sess.Close()
255			return nil, errors.New("sarvam hooks still need review after trust pre-seed — the e2e adapter's trusted_hash constants are stale for this sarvam-code version; recapture them via agents/entire-agent-sarvam/scripts/verify-sarvam.sh")
256		}
257		sess.stableAtSend = ""
258		return &sarvamSession{TmuxSession: sess}, nil
259	}
261	// seedSarvamHookTrust writes the [hooks.state] entries a completed /hooks
262	// review would persist: enabled = true plus the CLI's trusted_hash for each
263	// of the four hooks entire-agent-sarvam installs. Missing entries are
264	// appended; existing state for other repos is left untouched.
265	func seedSarvamHookTrust(repoDir string) error {
266		configPath := sarvamUserConfigPath()
267		if configPath == "" {
268			return errors.New("cannot resolve the sarvam user config for hook trust pre-seeding")
269		}
270		canonical, err := filepath.EvalSymlinks(repoDir)
271		if err != nil {
272			canonical = repoDir
273		}
275		data, err := os.ReadFile(configPath)
276		if err != nil && !os.IsNotExist(err) {
277			return err
278		}
279		content := string(data)
281		var addition strings.Builder
282		for _, state := range sarvamHookState {
283			key := canonical + "/.sarvam/config.toml:" + state.Event + ":0:0"
284			if strings.Contains(content, `"`+key+`"`) {
285				continue
286			}
287			addition.WriteString("\n[hooks.state.\"" + key + "\"]\n")
288			addition.WriteString("enabled = true\n")
289			addition.WriteString("trusted_hash = \"" + state.Hash + "\"\n")
290		}
291		if addition.Len() == 0 {
292			return nil
293		}
294		if err := os.MkdirAll(filepath.Dir(configPath), 0o755); err != nil {
295			return err
296		}
297		mode := os.FileMode(0o600)
298		if existing, err := os.Stat(configPath); err == nil {
299			mode = existing.Mode().Perm()
300		}
301		if len(content) > 0 && !strings.HasSuffix(content, "\n") {
302			content += "\n"
303		}
304		return os.WriteFile(configPath, []byte(content+addition.String()), mode)
305	}
307	// sarvamUserConfigPath resolves the CLI's user config carrying [hooks.state].
308	func sarvamUserConfigPath() string {
309		if v := os.Getenv("SARVAM_HOME"); v != "" {
310			return filepath.Join(v, "config.toml")
311		}
312		home, err := os.UserHomeDir()
313		if err != nil {
314			return ""
315		}
316		return filepath.Join(home, ".sarvam", "config.toml")
317	}

